package com.muthumol.player.dummy;
import android.content.*;import java.io.*;import java.util.*;
final class StorageReview {
 static long bytes(File f){if(!f.exists())return 0;if(f.isFile())return f.length();long n=0;File[] files=f.listFiles();if(files!=null)for(File file:files)n+=bytes(file);return n;}
 static void show(MainActivity a){File downloads=new File(a.getFilesDir(),"offline-videos");long free=a.getFilesDir().getUsableSpace();Ui.menu(a,"Storage · "+MainActivity.size(free)+" free",new String[]{"Clear temporary stream cache","Low-storage mode · "+a.getSharedPreferences("player",0).getBoolean("lowStorage",false),"Remove watched legacy downloads","Legacy download cleanup notifications · "+a.getSharedPreferences("alerts",0).getBoolean("downloads",true)},n->{if(n==0)a.clearVideoCache();else if(n==1){SharedPreferences p=a.getSharedPreferences("player",0);p.edit().putBoolean("lowStorage",!p.getBoolean("lowStorage",false)).apply();a.session.closeStore();}else if(n==2)cleanup(a);else{SharedPreferences p=a.getSharedPreferences("alerts",0);p.edit().putBoolean("downloads",!p.getBoolean("downloads",true)).apply();}});}
 static void cleanup(Context c){SharedPreferences p=c.getSharedPreferences("tv-downloads",0);TvLibrary library=new TvLibrary(c);int count=0;for(Map.Entry<String,?> e:p.getAll().entrySet())if(e.getKey().startsWith("ready:")&&e.getValue() instanceof String)try{Movie m=Movie.from(new org.json.JSONObject((String)e.getValue()));if(!library.marked(m,"watched"))continue;String id=e.getKey().substring(6);File f=new File(c.getFilesDir(),"offline-videos/"+id+".video");if(!f.exists()||f.delete()){p.edit().remove(e.getKey()).remove("status:"+id).apply();count++;}}catch(Exception ignored){}if(count>0)ContentAlerts.notice(c,"downloads","Removed "+count+" watched saved copies",2001);}
}
